import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"畫作同步","description":"地圖畫跨分流同步的申請及說明。","frontmatter":{"title":"畫作同步","description":"地圖畫跨分流同步的申請及說明。"},"headers":[],"relativePath":"apply/form_paint/index.md","filePath":"apply/form_paint.md"}'),r={name:"apply/form_paint/index.md"};function o(n,a,d,c,h,s){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="畫作同步" tabindex="-1">畫作同步 <a class="header-anchor" href="#畫作同步" aria-label="Permalink to &quot;畫作同步&quot;">​</a></h1><h2 id="相關連結" tabindex="-1">相關連結 <a class="header-anchor" href="#相關連結" aria-label="Permalink to &quot;相關連結&quot;">​</a></h2><p><font size="4"><a href="https://forms.gle/JyucQad43hSzLScY6" target="_blank" rel="noreferrer">畫作同步申請表單</a></font></p><h2 id="同步說明" tabindex="-1">同步說明 <a class="header-anchor" href="#同步說明" aria-label="Permalink to &quot;同步說明&quot;">​</a></h2><h3 id="申請流程" tabindex="-1">申請流程 <a class="header-anchor" href="#申請流程" aria-label="Permalink to &quot;申請流程&quot;">​</a></h3><ul><li>首先，請將你的畫作在製圖台利用玻璃片鎖定好，以及在鐵砧依照規則命名好 <ul><li>圖畫命名規則<b>橫列-直行</b>請務按照規則命名，否則會退件處理 <ul><li>例:星爆氣流斬1-1/星爆氣流斬1-2/星爆氣流斬2-1/星爆氣流斬2-2<br><img src="https://i.imgur.com/FjJE6X5.png" style="width:50%;"></li></ul></li></ul></li><li>接著，前往原始畫作所在分流的畫作同步區，將要同步的畫作擺放進木桶內，並拿告示牌鎖好 <ul><li>不要亂放其他東西 放進去的東西都不會還你</li></ul></li><li>放好後，請填寫表單，提交同步申請 <ul><li>當處理完成後會在表單上打上表情符號，代表處理完成</li></ul></li><li><font color="red"><b>在同步完成之前，請先不要將地圖攜帶跨服，這會造成損壞!</b></font></li></ul><h3 id="取得自己的畫作" tabindex="-1">取得自己的畫作 <a class="header-anchor" href="#取得自己的畫作" aria-label="Permalink to &quot;取得自己的畫作&quot;">​</a></h3><ul><li>可以輸入<code>/maplist</code>買自己的畫作(一張地圖5塊)</li><li>如果你在同步前有自己備份一套畫作的話，可以對著你留存的畫作輸入<code>/mapconvert</code>即可完成轉換</li></ul><h3 id="畫作同步區地點" tabindex="-1">畫作同步區地點 <a class="header-anchor" href="#畫作同步區地點" aria-label="Permalink to &quot;畫作同步區地點&quot;">​</a></h3><ul><li>主一 : 重生點<code>/spawn</code>的樓上</li><li>主二 : 重生點<code>/spawn</code>的樓下</li><li>主三 : 重生點的前往美術館的門背面</li></ul><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h3><ul><li>請務必按照申請流程進行準備，以加快同步作業 <ul><li>未按照說明處理畫作有可能會被退件，屆時請重新申請</li></ul></li><li>僅受理主一、主二及主三的同步申請，請務必將畫作蓋在前列分流的主世界或終界</li><li>申請作業需一定時間，請玩家耐心等候處理</li></ul>',12)])])}const f=l(r,[["render",o]]);export{p as __pageData,f as default};
